SERIAL = "P2404150000H3001"
IDENTITY = text_words("Pylon", 5) + text_words("ForceHB_H3", 5) + [0x0102] + [0] * 5


def bank() -> dict[int, int]:
    out: dict[int, int] = {}

    def put(start: int, words: list[int]) -> None:
        for offset, word in enumerate(words):
            out[start + offset] = word

    put(0x1000, IDENTITY)
    put(0x1100, SUMMARY)
    put(0x1400, SUMMARY)
    put(0x1450, text_words(SERIAL, 8))
    put(0x1460, MODULE_VOLTAGES + [0] * 10)
    put(0x14B0, MODULE_TEMPERATURES + [0] * 10)
    put(0x1500, CELLS)
    put(0x1800, CELL_TEMPERATURES)
    return out
